"use strict";
// What island code sees of a program object. Strict code, so a refused
// write or delete throws; `sloppy` holds the same operations in sloppy code.
const fact = (out, k, f) => {
  try {
    out.push(k + "=" + f());
  } catch (e) {
    out.push(k + "=!" + e.name);
  }
};
const shape = (d) =>
  d === undefined
    ? "none"
    : ("value" in d ? "data" : "accessor:" + (d.get ? "g" : "-") + (d.set ? "s" : "-")) +
      ":" +
      (d.enumerable ? "e" : "-") +
      ("value" in d && d.writable ? "w" : "-") +
      (d.configurable ? "c" : "-");
// Each name as an own property of the instance and as a member of its prototype.
exports.members = (v, names) => {
  const out = [];
  const proto = Object.getPrototypeOf(v);
  for (const name of names) {
    fact(out, name, () => `${name in v}/${Object.hasOwn(v, name)}/${shape(Object.getOwnPropertyDescriptor(v, name))}/${typeof v[name]}`);
    fact(out, "proto." + name, () => shape(Object.getOwnPropertyDescriptor(proto, name)));
  }
  return out.join(" ");
};
exports.reflect = (v) => {
  const out = [];
  fact(out, "keys", () => Object.keys(v).join(","));
  fact(out, "names", () => Object.getOwnPropertyNames(v).join(","));
  fact(out, "forin", () => {
    const ks = [];
    for (const k in v) ks.push(k);
    return ks.join(",");
  });
  fact(out, "entries", () => Object.entries(v).map(([k, x]) => k + ":" + typeof x).join(","));
  fact(out, "spread", () => Object.keys({ ...v }).join(","));
  fact(out, "json", () => JSON.stringify(v));
  fact(out, "String", () => String(v));
  fact(out, "tag", () => Object.prototype.toString.call(v));
  fact(out, "ctor", () => v.constructor.name);
  fact(out, "plain", () => Object.getPrototypeOf(v) === Object.prototype);
  fact(out, "protoKeys", () => Object.keys(Object.getPrototypeOf(v)).join(","));
  return out.join(" ");
};
exports.set = (v, k, x) => {
  try {
    v[k] = x;
    return "wrote";
  } catch (e) {
    return e.name;
  }
};
exports.get = (v, k) => {
  try {
    return String(v[k]);
  } catch (e) {
    return "!" + e.name;
  }
};
exports.call = (v, k, ...args) => {
  try {
    return String(v[k](...args));
  } catch (e) {
    return "!" + e.name;
  }
};
exports.remove = (v, k) => {
  try {
    return String(delete v[k]);
  } catch (e) {
    return e.name;
  }
};
exports.sameProto = (a, b) => Object.getPrototypeOf(a) === Object.getPrototypeOf(b);
exports.sloppy = {
  set: new Function("v", "k", "x", "try { v[k] = x; return 'wrote'; } catch (e) { return e.name; }"),
  remove: new Function("v", "k", "try { return String(delete v[k]); } catch (e) { return e.name; }"),
};
